function patchText(file, updater) {
  if (!fs.existsSync(full(file))) {
    console.log("[skip missing]", file);
    return;
  }
  const before = read(file);
  const after = updater(before);
  if (after !== before) {
    write(file, after);
    console.log("[patch]", file);
  } else {
    console.log("[no change]", file);
  }
}

